column1:
CREATE TABLE btm_rel ( -- Связи между счетами.
    r01 INTEGER, -- Идентификатор клиента.
    r02 TEXT   , -- Номер дочернего или связанного счета.
    r03 TEXT   , -- Тип связанного счета.
    r04 TEXT     -- Номер основного счета.
);

CREATE TABLE btm_msg ( -- Шаблоны клиентских уведомлений.
    m01 TEXT   , -- Событие уведомления.
    m02 TEXT   , -- Текст уведомления.
    m03 TEXT     -- Канал доставки уведомления.
);

CREATE TABLE btm_rate ( -- Процентные ставки по продуктам.
    i01 TEXT   , -- Тип банковского продукта.
    i02 REAL   , -- Процентная ставка.
    i03 TEXT   , -- Месяц действия ставки.
    i04 TEXT     -- Год действия ставки.
);
